 for(int c=0;c<5;c++){coax_t_OrSnapshot s=initial(c,ids[c]);coax_t_OsState legacy=s.state;for(int relative=0;relative<=length(c);relative++){if(relative<length(c))accept_event(c,relative,&s,0);
   if(capture_tick(c,relative)){CHECK(saved_count<24);saved[saved_count]=s;saved_case[saved_count]=c;saved_relative[saved_count]=relative;saved_count++;uint8_t bytes[1313];memset(bytes,0xa5,sizeof bytes);CHECK(or_encode(s,(coax_v_u8){bytes,1313},0)==0&&bytes[1312]==0xa5);CHECK(fwrite(bytes,1,1312,snapfile)==1312);if(c==0&&relative==43){memcpy(mid,bytes,1312);midstate=s;FILE*f=create(prefix,"mid");CHECK(fwrite(mid,1,1312,f)==1312&&fclose(f)==0);}}
   if(relative==length(c))break;coax_t_OsStep reference=os_step(s.params,legacy,input(c,relative),s.dt);coax_t_OrStep step=or_advance(s);CHECK(reference.status==0&&step.status==0);legacy=reference.state;CHECK(step.frame.tick==start_tick(c)+relative+1&&step.frame.force==word(input(c,relative))&&step.frame.position==word(legacy.position)&&step.frame.velocity==word(legacy.velocity));CHECK(word(step.snapshot.state.position)==step.frame.position&&word(step.snapshot.state.velocity)==step.frame.velocity);base[c][relative]=step.frame;CHECK(fwrite(&step.frame,sizeof step.frame,1,tracefile)==1);s=step.snapshot;original_steps++;CHECK(fegetround()==FE_TONEAREST&&control()==fp_control);
 }}
