 FILE*differences=create(prefix,"differences.json");fprintf(differences,"[\n");coax_t_OrFrame expected[128];coax_t_OrReplay truth=or_replay(midstate,(coax_v_t_OrFrame){expected,128},0);CHECK(truth.status==0&&truth.written==21);
 for(int omission=0;omission<4;omission++){coax_t_OrSnapshot changed=midstate;if(omission==0)changed.state=(coax_t_OsState){0,0};if(omission==1)changed.tick=0;if(omission==2)changed.dt=.03125;if(omission==3){changed.pending=0;for(int j=0;j<128;j++)changed.forces.e[j]=0;}uint8_t bytes[1312];CHECK(or_encode(changed,(coax_v_u8){bytes,1312},0)==0);coax_t_OrSnapshot out;CHECK(or_restore((coax_v_u8){bytes,1312},ids[0],(coax_v_t_OrSnapshot){&out,1},0)==0);coax_t_OrFrame actual[128];coax_t_OrReplay run=or_replay(out,(coax_v_t_OrFrame){actual,128},0);CHECK(run.status==0);coax_t_OrDifference d=or_first(ids[0],ids[0],(coax_v_t_OrFrame){expected,21},(coax_v_t_OrFrame){actual,run.written});CHECK(d.status==0&&!d.equal&&d.tick==44&&d.field==(omission==1?COAX_OrField_tick:(omission==3?COAX_OrField_length:COAX_OrField_position)));if(omission)fprintf(differences,",\n");const char*names[]={"changed-state","changed-clock","changed-dt","omitted-pending-inputs"};json_difference(differences,names[omission],d);}
 for(int fault=1;fault<=2;fault++){coax_t_OrSnapshot s;CHECK(or_restore((coax_v_u8){mid,1312},ids[0],(coax_v_t_OrSnapshot){&s,1},0)==0);coax_t_OrFrame actual[128];int n=0;for(int r=43;r<128;r++){if(r!=43)accept_event(0,r,&s,fault);coax_t_OrStep step=or_advance(s);if(step.status==COAX_OrStatus_empty)break;CHECK(step.status==0);actual[n++]=step.frame;s=step.snapshot;}coax_t_OrDifference d=or_first(ids[0],ids[0],(coax_v_t_OrFrame){base[0]+43,85},(coax_v_t_OrFrame){actual,n});CHECK(d.status==0&&!d.equal&&d.tick==65&&d.field==(fault==1?COAX_OrField_length:COAX_OrField_force));fprintf(differences,",\n");json_difference(differences,fault==1?"unaccepted-later-event-not-resupplied":"altered-later-acceptance",d);}
